import Database from 'better-sqlite3';
import { existsSync, mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { createHash } from 'node:crypto';

const PROJECT_ROOT = '/home/user/qwik-upload';
const DB_PATH = join(PROJECT_ROOT, 'db.sqlite');
const UPLOADS_DIR = join(PROJECT_ROOT, 'uploads');

export interface FileMetadata {
  originalName: string;
  storedName: string;
  size: number;
  sha256: string;
  contentType: string;
}

let db: any = null;

export function getDb() {
  if (!db) {
    if (!existsSync(UPLOADS_DIR)) {
      mkdirSync(UPLOADS_DIR, { recursive: true });
    }
    db = new Database(DB_PATH);
    db.pragma('journal_mode = WAL');
    db.exec(`
      CREATE TABLE IF NOT EXISTS files (
        originalName TEXT NOT NULL,
        storedName TEXT NOT NULL,
        size INTEGER NOT NULL,
        sha256 TEXT NOT NULL UNIQUE,
        contentType TEXT NOT NULL
      )
    `);
  }
  return db;
}

export function getFiles(): FileMetadata[] {
  const database = getDb();
  return database.prepare('SELECT originalName, storedName, size, sha256, contentType FROM files').all() as FileMetadata[];
}

export function getFileByStoredName(storedName: string): FileMetadata | null {
  const database = getDb();
  return database.prepare('SELECT originalName, storedName, size, sha256, contentType FROM files WHERE storedName = ?').get(storedName) as FileMetadata | null;
}

export function getFilePath(storedName: string): string {
  return join(UPLOADS_DIR, storedName);
}

export function sanitizeFilename(name: string): string {
  if (!name) return 'file';
  // Remove directory components by splitting by / and \
  const parts = name.split(/[/\\]/);
  let base = parts[parts.length - 1] || 'file';

  // If the base itself is '.' or '..' or empty, reset to 'file'
  if (base === '.' || base === '..') {
    base = 'file';
  }

  // Remove any occurrences of '..'
  base = base.replace(/\.\./g, '');

  // Remove double quotes to prevent HTTP header issues
  base = base.replace(/"/g, '');

  // Trim spaces
  base = base.trim();
  if (!base) base = 'file';
  return base;
}

export function saveFile(buffer: Buffer, originalName: string, contentType: 'image/png' | 'application/pdf') {
  const sha256 = createHash('sha256').update(buffer).digest('hex');
  const size = buffer.length;

  const ext = contentType === 'image/png' ? 'png' : 'pdf';
  const storedName = `${sha256}.${ext}`;
  const storedFilePath = join(UPLOADS_DIR, storedName);

  const database = getDb();

  // Check if a file with this sha256 already exists in DB
  const existing = database.prepare('SELECT originalName, storedName, size, sha256, contentType FROM files WHERE sha256 = ?').get(sha256) as FileMetadata | null;

  if (existing) {
    return {
      success: true,
      dedup: true,
      file: existing
    };
  }

  // Write file to filesystem if it doesn't exist
  if (!existsSync(storedFilePath)) {
    writeFileSync(storedFilePath, buffer);
  }

  // Try to insert into database
  try {
    database.prepare(`
      INSERT INTO files (originalName, storedName, size, sha256, contentType)
      VALUES (?, ?, ?, ?, ?)
    `).run(originalName, storedName, size, sha256, contentType);

    return {
      success: true,
      dedup: false,
      file: {
        originalName,
        storedName,
        size,
        sha256,
        contentType
      }
    };
  } catch (err: any) {
    // Unique constraint violation (race condition)
    if (err.code === 'SQLITE_CONSTRAINT_UNIQUE' || err.message?.includes('UNIQUE constraint failed')) {
      const concurrentExisting = database.prepare('SELECT originalName, storedName, size, sha256, contentType FROM files WHERE sha256 = ?').get(sha256) as FileMetadata;
      return {
        success: true,
        dedup: true,
        file: concurrentExisting
      };
    }
    throw err;
  }
}

import { component$ } from '@builder.io/qwik';
import { routeLoader$, routeAction$, Form } from '@builder.io/qwik-city';
import type { FileMetadata } from '../lib/storage';

export const useFileListLoader = routeLoader$(async () => {
  const { getFiles } = await import('../lib/storage');
  return getFiles();
});

export const useUploadAction = routeAction$(async (data, requestEvent) => {
  try {
    const formData = await requestEvent.request.formData();
    const file = formData.get('file');

    // 1. Validate missing or empty file
    if (!file || !(file instanceof Blob) || file.size === 0) {
      return { status: 'error', errorCode: 'no_file' };
    }

    // 2. Validate maximum size (1048576 bytes / 1 MiB)
    if (file.size > 1048576) {
      return { status: 'error', errorCode: 'file_too_large' };
    }

    // Convert to Buffer to check byte signature and compute hash
    const arrayBuffer = await file.arrayBuffer();
    const buffer = Buffer.from(arrayBuffer);

    if (buffer.length > 1048576) {
      return { status: 'error', errorCode: 'file_too_large' };
    }

    // 3. Validate content type from byte signature (PNG or PDF)
    let contentType: 'image/png' | 'application/pdf' | null = null;
    if (buffer.length >= 8) {
      const isPng = buffer[0] === 0x89 &&
                    buffer[1] === 0x50 &&
                    buffer[2] === 0x4e &&
                    buffer[3] === 0x47 &&
                    buffer[4] === 0x0d &&
                    buffer[5] === 0x0a &&
                    buffer[6] === 0x1a &&
                    buffer[7] === 0x0a;
      if (isPng) contentType = 'image/png';
    }
    if (!contentType && buffer.length >= 4) {
      const isPdf = buffer[0] === 0x25 &&
                    buffer[1] === 0x50 &&
                    buffer[2] === 0x44 &&
                    buffer[3] === 0x46;
      if (isPdf) contentType = 'application/pdf';
    }

    if (!contentType) {
      return { status: 'error', errorCode: 'unsupported_type' };
    }

    // Get client-declared original filename
    const filenameField = formData.get('filename');
    const clientFilename = typeof filenameField === 'string' ? filenameField : '';

    const { sanitizeFilename, saveFile } = await import('../lib/storage');

    const originalNameRaw = clientFilename || (file instanceof File ? file.name : '') || 'file';
    const originalName = sanitizeFilename(originalNameRaw);

    const result = saveFile(buffer, originalName, contentType);

    return {
      status: 'success',
      dedup: result.dedup,
    };
  } catch (err) {
    console.error('Upload action failed:', err);
    return { status: 'error', errorCode: 'no_file' };
  }
});

export default component$(() => {
  const fileList = useFileListLoader();
  const action = useUploadAction();

  return (
    <div style={{ padding: '20px', fontFamily: 'sans-serif' }}>
      <h1>Qwik City Secure File Upload Service</h1>

      <div style={{ marginBottom: '30px', border: '1px solid #ccc', padding: '15px', borderRadius: '5px' }}>
        <h2>Upload a File</h2>
        <Form action={action} encType="multipart/form-data">
          <div style={{ marginBottom: '10px' }}>
            <label style={{ display: 'block', marginBottom: '5px' }}>File (PNG or PDF, max 1MB):</label>
            <input type="file" name="file" accept=".png,.pdf" />
          </div>
          <div style={{ marginBottom: '15px' }}>
            <label style={{ display: 'block', marginBottom: '5px' }}>Original Filename:</label>
            <input type="text" name="filename" placeholder="Enter original filename" style={{ width: '100%', padding: '5px' }} />
          </div>
          <button type="submit" style={{ padding: '8px 15px', cursor: 'pointer' }}>Upload</button>
        </Form>
      </div>

      {action.value && (
        <div
          id="upload-result"
          data-status={action.value.status}
          {...(action.value.status === 'success'
            ? { 'data-dedup': action.value.dedup ? 'true' : 'false' }
            : { 'data-error-code': action.value.errorCode })}
          style={{
            padding: '10px',
            marginBottom: '20px',
            backgroundColor: action.value.status === 'success' ? '#e6f4ea' : '#fce8e6',
            color: action.value.status === 'success' ? '#137333' : '#c5221f',
            borderRadius: '4px'
          }}
        >
          {action.value.status === 'success' ? (
            <span>
              File uploaded successfully! {action.value.dedup ? '(Deduplicated)' : ''}
            </span>
          ) : (
            <span>
              Upload failed: {action.value.errorCode}
            </span>
          )}
        </div>
      )}

      <div>
        <h2>Stored Files</h2>
        {fileList.value.length === 0 ? (
          <p>No files uploaded yet.</p>
        ) : (
          <ul>
            {fileList.value.map((file) => (
              <li key={file.storedName} data-stored-name={file.storedName} style={{ marginBottom: '10px' }}>
                <strong>{file.originalName}</strong> ({file.contentType}, {file.size} bytes) -{' '}
                <a href={`/api/files/download/${file.storedName}`} download={file.originalName}>
                  Download
                </a>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
});

import type { RequestHandler } from '@builder.io/qwik-city';

export const onGet: RequestHandler = async ({ json }) => {
  const { getFiles } = await import('../../../lib/storage');
  const files = getFiles();
  json(200, files);
};

import type { RequestHandler } from '@builder.io/qwik-city';
import { existsSync, readFileSync } from 'node:fs';

export const onGet: RequestHandler = async ({ params, status, headers, send }) => {
  const { storedName } = params;
  const { getFileByStoredName, getFilePath } = await import('../../../../../lib/storage');

  const file = getFileByStoredName(storedName);
  if (!file) {
    status(404);
    send(404, 'File not found');
    return;
  }

  const filePath = getFilePath(storedName);
  if (!existsSync(filePath)) {
    status(404);
    send(404, 'File content not found on disk');
    return;
  }

  try {
    const buffer = readFileSync(filePath);
    headers.set('Content-Type', file.contentType);
    headers.set('Content-Disposition', `attachment; filename="${file.originalName}"`);
    send(200, buffer);
  } catch (err) {
    console.error('Download error:', err);
    status(500);
    send(500, 'Internal server error');
  }
};

